    if (str == null || suffix == null) return false;
    if (suffix.length() > str.length()) return false;
    int len = suffix.length();
    String startCase = str.substring(str.length() - len, str.length());
    if (ignoreCase) startCase = startCase.toLowerCase();
    return startCase.equals(suffix);
}

