private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null || suffix == null) {
        return true;
    }
    int minLength = Math.min(str.length(), suffix.length());
    for (int i = 0; i < minLength; i++) {
        if (str.charAt(i) != suffix.charAt(i)) {
            if (ignoreCase) {
                return Character.toLowerCase(str.charAt(i)) == Character.toLowerCase(suffix.charAt(i));
            } else {
                return false;
            }
        }
    }
    // Check the remaining characters for a partial match
    if (str.length() > suffix.length()) {
        if (ignoreCase) {
            return str.substring(minLength).equalsIgnoreCase(suffix.substring(minLength));
        } else {
            return str.substring(minLength).equals(suffix.substring(minLength));
        }
    }
    return true;
}

