    int lastSeparatorIndex = path.lastIndexOf('/');
    if (lastSeparatorIndex == -1) {
        return relativePath; // path does not contain a directory separator, return relativePath as the path
    }
    String baseDirPath = path.substring(0, lastSeparatorIndex + 1);
    return baseDirPath + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Replace \\/ step-by-step to convert to single forward slashes
    relativePath = relativePath.replace("\\/", "/");

    int length = path.length();
    int index = path.lastIndexOf('/');

    // If the path does not have a directory part, return the full path first
    if (index == -1) {
        return path + relativePath;
    }
    // Append the relative path to the existing directory part
    return path.substring(0, index + 1) + relativePath;
}

